//! Boba Job Find — Tauri core entry point.
//!
//! Registers every MVP plugin so later slices do not edit this file
//! (backlog ownership convention 8): single-instance (AD-18), tray (feature),
//! notification, autostart, global-shortcut, log, updater + process.
//! Commands live under [`commands`] and are listed in [`commands::registry`].

mod autostart;
mod commands;
mod events;
mod ipc;
mod lifecycle;
mod notifications;
mod scheduler;
mod shortcuts;
mod tray;

/// Build and run the desktop application.
#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let builder = tauri::Builder::default()
        // Must be the first plugin registered.
        .plugin(tauri_plugin_single_instance::init(|_app, _argv, _cwd| {}))
        .plugin(tauri_plugin_notification::init())
        .plugin(tauri_plugin_autostart::Builder::new().build())
        .plugin(tauri_plugin_global_shortcut::Builder::new().build())
        .plugin(tauri_plugin_log::Builder::new().build())
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_window_state::Builder::default().build());

    #[cfg(desktop)]
    let builder = builder.plugin(tauri_plugin_process::init()).setup(|app| {
        app.handle()
            .plugin(tauri_plugin_updater::Builder::new().build())?;
        // Registry is the single source of command paths (AD-3).
        let _ = commands::registry::COMMANDS;
        Ok(())
    });

    builder
        .run(tauri::generate_context!())
        .expect("error while running Boba Job Find");
}
